import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第04章 老婆","description":"","frontmatter":{},"headers":[],"relativePath":"第04章_老婆.md","filePath":"第04章_老婆.md"}'),o={name:"第04章_老婆.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第04章-老婆" tabindex="-1">第04章 老婆 <a class="header-anchor" href="#第04章-老婆" aria-label="Permalink to &quot;第04章 老婆&quot;">​</a></h1><p>腊月二十九，天阴了一整天，没下下来。</p><p>奶奶在厨房里炸东西，油锅的声音从里屋一直响到客厅。我在旁边帮着递盘子，手上全是面。炸好的东西摊在报纸上，一格一格摆开，晾着。</p><p>手机在裤兜里震了一下。我把手在围裙上擦干净，掏出来看，是她。</p><p>「在干嘛」</p><p>我说，帮我奶奶炸东西。</p><p>她说，你家还自己炸啊。</p><p>我说，每年都炸。</p><p>她说，我家的都是买的。</p><p>我说，买的也好。</p><p>她说，你到底会不会聊天。</p><p>我不知道怎么接，就没接。过了一分钟，她换了个话题。</p><p>「给你看个东西」</p><p>然后是一张图。屏幕上是一只猫，蹲在一堆纸箱子上，眼神很不耐烦。图下面配了一行字，我没看懂。</p><p>我说，这是你家的猫？</p><p>她说，不是，网图。</p><p>我说，哦。</p><p>她说，你这个人。</p><p>我说，怎么了。</p><p>她说，你就不能笑一下吗。</p><p>我说，我笑了。</p><p>她说，我看不见。</p><p>我说，那我发个表情。</p><p>我翻了半天，发了一个笑脸过去。</p><p>她说，这个表情看着很假。</p><p>我说，那我换一个。</p><p>她说，算了。</p><p>隔了几秒，她又发来一条。</p><p>「我心情不好」</p><p>我问，怎么了。</p><p>她说，没什么，就是不好。</p><p>我说，那你说说。</p><p>她说，不说。</p><p>我说，那我不问了。</p><p>她说，你也不哄一下。</p><p>我看着这句话愣了一下。哄，这个字我没用过。我想了想，打了一句：那你怎么才能好。</p><p>她说，不知道。</p><p>她说，你陪着我就行。</p><p>那天的谈话就这么过去了。她后来又发了几张图，都是些没什么意义的东西，一只鞋，一盒抽纸，窗外的一小块天。我一张一张回，好，嗯，看到了。</p><p>到了晚上，奶奶睡了，我一个人在屋里。她忽然发来一条。</p><p>「你能不能叫我一声」</p><p>我说，叫你什么。</p><p>她说，随便你。</p><p>我说，那叫你名字？</p><p>她说，不行。</p><p>我说，为什么。</p><p>她说，太生分了。</p><p>我想了半天，问了句：那我叫你什么算合适。</p><p>她过了很久才回。回来的是三个字：</p><p>「叫声老婆试试」</p><p>我盯着这三个字看了半天。</p><p>那时候我正在被子里，屋里没开灯，屏幕的光照在天花板上，晃着一小片。奶奶的呼吸声从隔壁传过来，很轻。</p><p>我打了一个字，删了。又打了两个字，又删了。</p><p>最后我发出去的是：你确定？</p><p>她说，我就随便说说。</p><p>她说，你当我没说。</p><p>我说，那你说了。</p><p>她说，我说了又怎么了。</p><p>我那时候不知道自己是怎么想的。我打了一行字，发出去。</p><p>那行字是：老婆。</p><p>发出去的一瞬间我就想撤回了。手指已经按下去，屏幕上那两个字往上一跳，进到了上面，撤不回来了。</p><p>对面安静了很久。久到我以为她生气了，正准备说点别的把这事岔开。</p><p>然后她回了一串。</p><p>「哈哈哈」</p><p>「你这个人」</p><p>「睡觉！」</p><p>三个感叹号，一个比一个有劲。</p><p>我说，你先说的。</p><p>她说，我随口说的。</p><p>我说，我当真了。</p><p>她说，你这个人真烦。</p><p>我说，那我不叫了。</p><p>她说，随你。</p><p>隔了半分钟，又来一条。</p><p>她说，明天再说。</p><p>那时候我还不懂&quot;明天再说&quot;是什么意思。我以为那是一个拒绝。</p><p>第二天早上我醒得早，天还没亮，我把手机摸过来。她半夜三点多发过一条。</p><p>只有两个字。</p><p>「傻了」</p><p>我没回。我不知道回什么好。我坐起来，奶奶已经在厨房里烧水了，壶盖被顶得响。窗外是南雾县冬天早上的那种灰，什么都看不清。</p><p>我洗漱完，吃早饭的时候，手机上又来了一条。</p><p>她说，昨晚的事别放心上。</p><p>我说，好。</p><p>她说，你那句我看到了。</p><p>我说，嗯。</p><p>她说，就这一次。</p><p>我说，好。</p><p>她说，你别老说好。</p><p>我说，行。</p><p>她说，……</p><p>那天下午，她又来找我。话题已经换了一个，说的是她妹妹打碎了一只碗，她妈让她去扫。她讲得很细，碎瓷片怎么扫都扫不干净，她蹲在地上捡了半个小时。</p><p>我听着，忽然问了句我一直想问的话：你昨天为什么让我那么叫。</p><p>她说，我不是说了吗，随便说说。</p><p>我说，那你为什么半夜发那两个字。</p><p>她说，哪两个字。</p><p>我说，傻了。</p><p>她说，我忘了。</p><p>她说，你记那么清干什么。</p><p>然后她就把话题扯走了。扯到她家门口那只野猫，扯到她新买的笔，扯到年后要开学。她说了很多，一句都没提昨天。</p><p>我也就没再问。</p><p>那天晚上，我关了灯躺在床上，翻来覆去睡不着。我想起她说&quot;叫声老婆试试&quot;，想起她说&quot;就这一次&quot;，又想起她半夜发的那两个字。</p><p>我给她的备注改了。改完看着那一行字，觉得有点傻，又改回去了。</p><p>后来我反复改过几次。有一次改成了一个很奇怪的东西，第二天自己都忘了那是什么意思。还有一次我干脆把备注清空，只留了她的名字。清空了反倒看着别扭，像是笔画少了一笔。</p><p>最后还是改回了原来的。</p><p>过了两天，她又喊了一声。</p><p>那天是除夕。零点前几分钟，她发来一句：老婆，新年快乐。</p><p>后来我也回了一句。回完我把手机扣在枕头上，自己在黑屋子里坐了一会儿。</p><p>窗外有人放炮。一朵接一朵，炸完了就是烟，烟散了什么都没有。我一直觉得那年的炮声比往年响，也可能是我记错了。</p><p>奶奶睡得早，零点的时候她早就睡下了。我趴在窗台上看了一会儿。楼下有小孩在跑，手里拿着那种电光的棍子，一晃一晃。远处有人家在阳台上挂灯笼，红的，被风吹得转过来又转过去。</p><p>我把手机拿起来又放下。想给她发点什么，又觉得没什么可发的。</p><p>我没跟她说，那天晚上我想了很多。</p><p>我想的是，这两个字我们从头到尾都是当着玩笑叫的。谁都没说这两个字是什么意思，可谁都知道，叫了就是叫了。</p><p>那年的冬天只有这么长。开春再说吧，我那时候是这么想的。</p>',113)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
